<?php require dirname(__DIR__).'/includes/bootstrap.php';require APP_ROOT.'/services/auth.php';$u=require_role(['KHACH_HANG','NHAN_VIEN','ADMIN']);handle_form(function()use($u){throttle('change-password',(string)$u['id'],6,900);$old=$_POST['old']??'';$new=$_POST['new']??'';must(is_string($old)&&password_verify($old,$u['password']),'Mật khẩu hiện tại chưa đúng.');must(is_string($new)&&strlen($new)>=10&&strlen($new)<=72&&$new===($_POST['confirm']??''),'Mật khẩu mới cần 10–72 byte, xác nhận phải giống nhau.');execute('UPDATE tai_khoan SET password=?,phien_ban_xac_thuc=phien_ban_xac_thuc+1 WHERE id=?',[password_hash($new,PASSWORD_DEFAULT),$u['id']]);audit('DOI_MAT_KHAU','tai_khoan',(string)$u['id']);$_SESSION=[];session_regenerate_id(true);flash('Đã đổi mật khẩu và thu hồi các phiên cũ. Vui lòng đăng nhập lại.');redirect($u['quyen']==='ADMIN'?'admin/dang_nhap.php':'dang_nhap.php');},'khach_hang/doi_mat_khau.php');page_start('Đổi mật khẩu');echo '<div class="auth panel">';token_form();field('old','Mật khẩu hiện tại','','password','required');field('new','Mật khẩu mới','','password','required minlength="10"');field('confirm','Nhập lại mật khẩu mới','','password','required');echo '<button>Đổi mật khẩu</button></form></div>';page_end();
